"""Static completeness checks for the HTML generated by LeanBlueprint."""
from pathlib import Path
import json
import re
from html import unescape
from html.parser import HTMLParser
from urllib.parse import unquote

root = Path(__file__).resolve().parents[1]
data = json.loads((root / 'blueprint/dependencies.json').read_text(encoding='utf-8'))
web = root / 'blueprint/web'
graph = (web / 'dep_graph_document.html').read_text(encoding='utf-8')


class IDs(HTMLParser):
    def __init__(self):
        super().__init__()
        self.ids = set()
        self.local_assets = []
        self.declarations = set()

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if 'id' in attrs:
            self.ids.add(attrs['id'])
        if tag == 'a' and attrs.get('href', '').startswith('lean/find/#doc/'):
            self.declarations.add(unquote(attrs['href'].split('#doc/', 1)[1]))
        if tag == 'script' and 'src' in attrs:
            self.local_assets.append(attrs['src'])


parser = IDs()
parser.feed(graph)
missing = [n['id'] for n in data['nodes'] if n['id'] + '_modal' not in parser.ids]
assert not missing, f'Missing graph nodes: {missing}'
assert '.renderDot(' in graph, 'Missing dependency graph data'
final_node = next(n for n in data['nodes'] if n['id'] == 'thm:preiss')
assert all(name in graph for name in final_node['lean'])
if any(n['lean'] and n['status'] in {'unproved_statement', 'depends_on_unproved', 'definition_depends_on_unproved'} for n in data['nodes']):
    assert any('sorry' in p.read_text(encoding='utf-8') for p in web.glob('*.html')), 'Missing unfinished-proof disclosure'
for asset in parser.local_assets:
    if not re.match(r'^(https?:)?//', asset):
        assert (web / asset).is_file(), f'Missing JavaScript: {asset}'
assert (root / 'blueprint/lean_decls').is_file()
print(f'LeanBlueprint HTML contains all {len(data["nodes"])} graph modals and local scripts.')
print('This is a static completeness check, not a browser or mathematical verification.')

expected = {name for node in data['nodes'] for name in node['lean']}
assert parser.declarations == expected, 'Missing or unexpected Lean hyperlinks'
assert (web / 'lean/find/index.html').is_file(), 'Missing source viewer'
index = json.loads((web / 'lean/find/declarations.json').read_text(encoding='utf-8'))
assert index.keys() == expected, 'Source viewer index does not match graph'
assert "#doc/" in (web / 'lean/find/index.html').read_text(encoding='utf-8')
print(f'All {len(expected)} Lean links resolve through the source viewer index.')

checkpoint = json.loads((root / 'blueprint/kernel-checkpoint.json').read_text(encoding='utf-8'))
proof_page = (web / 'proof-status.html').read_text(encoding='utf-8')
assert checkpoint['source_revision'] in proof_page, 'Proof page has the wrong checkpoint'
assert {unescape(name) for name in re.findall(r'data-name="([^"]+)"', proof_page)} == set(checkpoint['declarations']), (
    'Proof page does not contain every audited declaration')
print(f"Verified proof list contains all {len(checkpoint['declarations'])} checkpoint declarations.")

# Check the actual interactive graph colours, not just a separate status page.
colors = json.loads((web / 'kernel-colors.json').read_text(encoding='utf8'))
assert colors['source_revision'] == checkpoint['source_revision']
dot_match = re.search(r'\.renderDot\(`([\s\S]*?)`\)', graph)
assert dot_match, 'Missing rendered DOT data'
dot = dot_match[1]
green = {'#1CAC78', '#9CEC8B', '#B0ECA3'}
for label, status in colors['nodes'].items():
    node = re.search(r'(?:^|;)\s*"' + re.escape(label) + r'"\s*\[([^\]]*)\]', dot)
    assert node, f'Missing rendered node attributes: {label}'
    fill = re.search(r'\bfillcolor\s*=\s*"?([^",\s\]]+)', node[1])
    is_green = bool(fill and fill[1] in green)
    assert is_green == status['proof_checked'], f'Incorrect proof colour: {label}'
print(f"Interactive graph colours match the kernel audit for all {len(colors['nodes'])} nodes.")
